using NCICParser.Interfaces;
using NCICParser.Models;
using System.Diagnostics;
using System.Text;
using System.Text.RegularExpressions;

namespace NCICParser.Services;

/// <summary>
/// Parses the NCIC Code Manual text generated by
/// Poppler's pdftotext utility.
///
/// The parser discovers section sections, subsections,
/// column definitions, category-list relationships,
/// and code rows before performing several
/// normalization passes.
/// </summary>
public class Parser(
    INCICFileReader fileReader)
        : IParser
{
    private INCICFileReader FileReader { get; init; } = fileReader ??
        throw new ArgumentException("File Reader cannot be null");

    /// <summary>
    /// Tracks the current segment parsing status
    /// </summary>
    private enum ParseState
    { 
        // Starting parsing at the section header
        InSectionHeader = 0,

        // Now expecting the code header (if any)
        ExpectCodeHeader = 1,

        // Now in the code list for parsing codes
        InCodeList = 2,
    }

    /// <summary>
    /// Cache storage for executed Regex to reduce new instances from spinning up.
    /// </summary>
    private static readonly Dictionary<string, Regex> _codeListRegex = [];

    // These codes were found to be preceding prose text
    // and not another code, but were the last item in
    // their respective list, so they should signal done.
    private static readonly HashSet<string> knownDones = [
        "ZVI", 
        "X*"
    ];

    // These codes were found to have 2 blank lines between
    // them and the next code instead of just 1.
    private static readonly HashSet<string> blanksFollowing2 = [
        "EMULTIM", 
        "HBUFFER", 
        "DV0ICER",
    ];

    /// <summary>
    /// Entry point for parsing the text file containing the known
    /// NCIC codes
    /// </summary>
    /// <param name="filePath">Full file path to the NCIC text file (including extension)</param>
    /// <returns>List of parsed Sections containing all parsed content</returns>
    public List<Section> Parse(string filePath, string dateEoPText)
    {
        var lines = FileReader.ReadFile(filePath);
        var returnValue = GetSections(lines);

        foreach (var section in returnValue)
        {
            section.SubSections = GetSubSections(lines, section);

            // Some sections don't have any identifiable SubSections
            if (section.SubSections.Count == 0)
                continue;

            // Make sure last subsection in each section
            // stops just before a new section begins (contains content)
            CloseSubSections(returnValue);

            // Now we have the encasulated row ranges to do the subsection parses
            foreach (var subSection in section.SubSections)
                subSection.CodeItemRows = ParseSubSection(lines, subSection, dateEoPText);
        }

        // At this point, we're likely to have multiple duplicated section and subsection
        // objects, as well as CodeItemRows that are actually continuations of previous
        // rows.  The following will crunch them all back to a single instance of each
        // respective artifact where it determines duplication or extension as applicable.
        CollapseAll(returnValue);

        return returnValue;
    }

    /// <summary>
    /// Collapses duplicate sections, subsections, and code item rows into single instances.
    /// </summary>
    /// <param name="sections">The sections to collapse.</param>
    private static void CollapseAll(List<Section> sections)
    {
        CollapseSections(sections);
        foreach (var section in sections)
        {
            CollapseSubSections(section.SubSections);
            foreach (var subsection in section.SubSections)
                CollapseCodeItemRows(subsection.CodeItemRows);
        }
    }

    /// <summary>
    /// Gets all the sections
    /// </summary>
    /// <param name="lines">List of Raw Lines</param>
    /// <returns>List of Sections</returns>
    private static List<Section> GetSections(List<RawLine> lines)
    {
        // Note: This *will* end up with adjacent duplicate sections, and
        // THAT'S OK, we'll compress them later in a post process.  This
        // way makes it much easier to process the file iteratively.
        List<Section> returnValue = [];
        List<RawLine> tocLines = [.. lines.Where(l => l.IsTableOfContents)];
        Section? lastSection = null;

        foreach (var tocLine in tocLines)
        {
            StringBuilder sectionName = new();
            int idx = lines.IndexOf(tocLine);

            // Seek back to the FF to find the actual start line of the section name
            for (int i = idx - 1; i >= 0; i--)
            {
                if (sectionName.Length > 0)
                    sectionName.Insert(0, lines[i].Text.Trim() + " ");
                else
                    sectionName.Append(lines[i].Text.Trim());

                if (lines[i].IsFormFeedLine)
                {
                    RawLine line = lines[i];
                    string temp = sectionName.ToString();

                    Section newSection = new(line, temp);
                    returnValue.Add(newSection);

                    // Last Section (if any, ends with the start of this one)...
                    lastSection?.FileLineNumberEnd = newSection.SourceLine.FileLineNumber - 1;
                    lastSection = newSection;
                    break;
                }
            }
        }

        return returnValue;
    }

    /// <summary>
    /// Gets all sections for the specified Section
    /// </summary>
    /// <param name="lines">List of Raw Lines</param>
    /// <param name="section">Current Section</param>
    /// <returns>List of SubSections for this section</returns>
    private static List<SubSection> GetSubSections(List<RawLine> lines, Section section)
    {
        // Note: This *will* end up with adjacent duplicate sections, and
        // THAT'S OK, we'll compress them later in a post process.  This
        // way makes it much easier to process the file interatively.

        List<SubSection> returnValue = [];
        SubSection? lastSubSection = null;

        // Get all the section start lines within this section...
        List<RawLine> subSectionLines = [.. lines.Where(i => i.IsSectionHeader
                                                     && i.FileLineNumber > section.SourceLine.FileLineNumber
                                                     && (i.FileLineNumber <= section.FileLineNumberEnd
                                                        || section.FileLineNumberEnd == -1))];

        foreach (RawLine subSectionLine in subSectionLines)
        {
            // Only interested in building the section object,
            // NOT parsing the section content just yet...
            StringBuilder sectionName = new();
            for (int i = subSectionLine.Index; i < lines.Count; i++)
            { 
                RawLine curLine = lines[i];
                if (curLine.IsNullOrWhiteSpace)
                {
                    var newSection = new SubSection(subSectionLine, sectionName.ToString());
                    lastSubSection?.FileLineNumberEnd = newSection.SourceLine.FileLineNumber - 1;
                    returnValue.Add(newSection);
                    lastSubSection = newSection;

                    break;
                }
                else
                {
                    if (sectionName.Length > 0)
                        sectionName.Append(' ');

                    sectionName.Append(curLine.Text.Trim());
                }
            }
        }

        return returnValue;
    }

    /// <summary>
    /// Determines the last line of each section to encapsulate the
    /// parsing scope.
    /// </summary>
    /// <param name="sections">List of Sections</param>
    private static void CloseSubSections(List<Section> sections)
    {
        for (var i = 0; i < sections.Count - 1; i++)
        {
            var section = sections[i];
            if (section.SubSections.Count == 0)
                continue;

            section.SubSections[^1].FileLineNumberEnd = sections[i + 1].SourceLine.FileLineNumber - 1;
        }

        // NOTE: the very last SubSection end is left at -1 to give indeterminate range, and thus
        // will stop when it determines a stopping point programatically.
    }

    /// <summary>
    /// Triggered when parsing a code list when the number of blank
    /// lines exceeds the threshold count (depending on last code)
    /// </summary>
    /// <param name="lines">List of RawLines</param>
    /// <param name="startIndex">Index of the latest blank line encountered</param>
    /// <param name="lastCode">Last valid code processed before this occurrence</param>
    /// <returns>true if parsing is done, or false if not done</returns>
    private static bool IsDoneParsing(List<RawLine> lines, int startIndex, string? lastCode)
    {
        // Some codes are known to be at the end of a list, but have prose text following
        // that if allowed to continue would be flagged as non-matching text, so we'll 
        // just head that off here.
        if (lastCode is not null && knownDones.Contains(lastCode))
            return true;

        for (int i = startIndex; i < lines.Count - 1; i++)
        { 
            RawLine line = lines[i];
            if (line.IsNullOrWhiteSpace)
                continue;

            // Near bottom of every page?
            else if (line.IsDateLine && line.Text.Trim() == Constants.PDF_FILE_DATE_2026)   
                return true;

            // A category line is next?
            else if (line.IsCategoryLine)
                return true;

            // Some other non-blank to consider..
            else
                return false;
        }

        return true;
    }

    /// <summary>
    /// Captures the code list category (if any)
    /// </summary>
    /// <param name="lines">List of RawLines</param>
    /// <param name="startIndex">Index of the line just above a code list header</param>
    /// <returns>The list category name (if any)</returns>
    private static string GetCategory(List<RawLine> lines, int startIndex)
    {
        var stack = new Stack<string>();

        for (int i = startIndex; i >= 0; i--)
        {
            var line = lines[i];

            if (line.IsNullOrWhiteSpace)
                break;

            stack.Push(line.Text.Trim());
        }

        return string.Join(' ', stack);
    }

    /// <summary>
    /// Determines the blank line tolerance between code row items
    /// </summary>
    /// <param name="code">Current code to set from</param>
    /// <returns>Number of blank lines expected from current code to next</returns>
    private static int GetBlankTolerance(string code) =>
        blanksFollowing2.Contains(code)
         ? 2
         : 1;

    /// <summary>
    /// Parses the current section
    /// </summary>
    /// <param name="lines">List of RawLines</param>
    /// <param name="subSection">Current SubSection</param>
    /// <param name="dateEoPValue">Date on the bottom of each page</param>
    /// <returns>Fully parsed section content</returns>
    private static List<CodeItemRow> ParseSubSection(List<RawLine> lines, SubSection subSection, string dateEoPValue)
    {
        List<CodeItemRow> returnValue = [];
        List<RawLine> sectionLines = [.. lines.Where(i => i.FileLineNumber > subSection.SourceLine.FileLineNumber
                                                      && i.FileLineNumber <= subSection.FileLineNumberEnd)];

        // Since the section start contains the section name, we have to find the first blank to know 
        // we're past the name.
        string? lastValidCode = null;
        int blankTolerance = 1;
        var category = "";
        var parseState = ParseState.InSectionHeader;
        var parsePattern = string.Empty;
        var blankCount = 0;

        foreach (var line in sectionLines)
        {
            //Debug.Print($"Page: {line.PageNumber}, FileLine: {line.FileLineNumber}, \"{line.Text}\"");

            // There's always a blank line following the header..
            if (parseState == ParseState.InSectionHeader && line.IsNullOrWhiteSpace)
            {
                parseState = ParseState.ExpectCodeHeader;
            }

            // Have we hit the bottom of a page?
            else if (line.Text == dateEoPValue)
            {
                break;
            }

            else if (parseState == ParseState.ExpectCodeHeader)
            {
                if (! line.IsNullOrWhiteSpace && line.IsCodeHeader)
                {
                    // Get our code headers...
                    subSection.CodeColumns = line.GetColumnSpecs();
                    parsePattern = subSection.GetCodeRegExPattern();
                    parseState = ParseState.InCodeList;
                    blankCount = 0;

                    // Set category item (if any)...
                    category = GetCategory(lines, line.Index - 1);
                }
            }
            
            else if (parseState == ParseState.InCodeList)
            {
                // Usually code sets are separated by multiple blank lines, 
                // while a code list will separate each code line by a single
                // blank line.. AGAIN this is usual, but not always, so depending
                // on the last code item, we'll set a tolerance and if hit,
                // check further to see if it's really done or an issue.
                if (line.IsNullOrWhiteSpace)
                {
                    if (++blankCount > blankTolerance)
                    {
                        // Determine if we're actually done (nothing but empty page following up to the date line...)
                        if (!IsDoneParsing(lines, line.Index, lastValidCode))
                        {
                            Debug.WriteLine(
                                 $"Blank Tolerance Hit | " +
                                 $"Section: {subSection.Name} | " +
                                 $"Page: {line.PageNumber} | " +
                                 $"Page Line: {line.PageLineNumber} | " +
                                 $"File Line: {line.FileLineNumber} | " +
                                 $"Last Code: '{lastValidCode}'"
                             );
                        }
                        
                        // Otherwise, just reset...
                        parseState = ParseState.ExpectCodeHeader;
                        blankCount = 0;
                    }
                }
                else
                {
                    // Parse the current row...
                    CodeItemRow row = ParseRow(line, category, parsePattern);

                    if (row.CodeItemValues[0].Length > 0)
                    { 
                        lastValidCode = row.CodeItemValues[0];
                        blankTolerance = GetBlankTolerance(lastValidCode);
                    }
                    returnValue.Add(row);

                    // Reset blank counter
                    blankCount = 0;
                }
            }
            
            else
            {
                // Nothing we want to do here...
            }
        }

        return returnValue;
    }

    /// <summary>
    /// Creates or Retrieves the appropriate Regex engine for this pattern
    /// </summary>
    /// <param name="pattern">Current pattern</param>
    /// <returns>Applicable Regex engine for the pattern</returns>
    private static Regex GetRegexForPattern(string pattern)
    {
        if (!_codeListRegex.TryGetValue(pattern, out Regex? regex))
        {
            regex = new Regex(pattern, RegexOptions.Compiled);
            _codeListRegex.Add(pattern, regex);
        }
        
        return regex;
    }

    /// <summary>
    /// Parses the current code row
    /// </summary>
    /// <param name="line">Current RawLine</param>
    /// <param name="category">Category code (if any)</param>
    /// <param name="pattern">Regex Pattern used to parse</param>
    /// <returns>CodeItemRow containing code content for this line</returns>
    private static CodeItemRow ParseRow(RawLine line, string category, string pattern)
    {
        // Make sure the text is wide enough for the pattern to handle as fixed width.
        string text = line.Text.PadRight(255);

        var regex = GetRegexForPattern(pattern);
        Match match = regex.Match(text);

        CodeItemRow returnValue = new(line)
        {
            Rejected = !match.Success,
            CategoryRaw = category
        };

        if (match.Success)
        {
            for (int i = 1; i < match.Groups.Count; i++)
            {
                returnValue.CodeItemValues.Add(match.Groups[i].Value.Trim());
            }
        }

        return returnValue;
    }

    /// <summary>
    /// Collapses duplicated sections into the first occurrence. 
    /// </summary>
    /// <param name="sections">List of Sections</param>
    private static void CollapseSections(List<Section> sections)
    {
        int idx = 0;
        while (idx < sections.Count - 1)
        {
            Section root = sections[idx];
            Section test = sections[idx + 1];

            if (root.Name == test.Name)
            {
                root.SubSections.AddRange(test.SubSections);
                root.FileLineNumberEnd = test.FileLineNumberEnd;
                sections.Remove(test);
            }
            else if (root.SubSections.Count == 0)
                sections.Remove(root);
            else
                idx++;
        }
    }

    /// <summary>
    /// Collapses duplicated segments into the first occurrence
    /// </summary>
    /// <param name="subSections">List of SubSections</param>
    private static void CollapseSubSections(List<SubSection> subSections)
    {
        int idx = 0;
        while (idx < subSections.Count - 1)
        {
            SubSection root = subSections[idx];
            SubSection test = subSections[idx + 1];

            if (root.Name == test.Name)
            {
                root.CodeItemRows.AddRange(test.CodeItemRows);
                root.FileLineNumberEnd = test.FileLineNumberEnd;
                subSections.Remove(test);
            }
            else if (root.CodeItemRows.Count == 0)
                subSections.Remove(root);
            else
                idx++;
        }
    }

    /// <summary>
    /// Collapses extended code item rows into a single row
    /// </summary>
    /// <param name="rows">List of CodeItemRows</param>
    private static void CollapseCodeItemRows(List<CodeItemRow> rows)
    {
        int idx = 0;
        while (idx < rows.Count - 1)
        {
            CodeItemRow test = rows[idx + 1];

            // No code means it was a row of additional values
            // from a previous row.
            if (test.CodeItemValues[0].Length == 0)
            {
                CodeItemRow root = rows[idx];

                for (var i = 0; i < test.CodeItemValues.Count; i++)
                    if (test.CodeItemValues[i].Length > 0)
                        root.CodeItemValues[i] += " " + test.CodeItemValues[i];

                rows.Remove(test);
            }
            else
                idx++;
        }
    }

}
